\begin{corollary}\label{cor_main}
Let $A/C$ be as in \autoref{main_thm} and assume that $A_\eta$ has no abelian subvarieties defined over $k$. Then the set map
$$\MW(A/C)/{\tors} \to  N_{1}(A)$$
$$Z \mapsto [Z]-[Z_0]$$
is injective.
\end{corollary}
